From 7772e2541cae85f0d0bd17e50ac7a22ba4127e85 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:38:57 +0100
Subject: [PATCH] kded: Unmute the default microphone with the mute shortcut
 when muted

When the microphone had been muted in the applet, the mute shortcut only
toggled the global mute on top of it, so the microphone stayed muted no
matter how often it was pressed. Now the shortcut unmutes it instead.

BUG: 511276
---
 src/kded/audioshortcutsservice.cpp | 6 +++++-
 1 file changed, 5 insertions(+), 1 deletion(-)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..4dda12bd 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -182,8 +182,12 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
     muteMicAction->setText(i18n("Mute Microphone"));
     muteMicAction->setShortcuts({Qt::Key_MicMute, Qt::MetaModifier | Qt::Key_VolumeMute});
     connect(muteMicAction, &QAction::triggered, this, [this]() {
-        if (m_globalConfig->globalMuteSources()) {
+        const auto source = m_preferredDevice.source();
+        if (m_globalConfig->globalMuteSources() || (source && source->isMuted())) {
             disableGlobalSourceMute();
+            if (source) {
+                source->setMuted(false);
+            }
         } else {
             enableGlobalSourceMute();
         }
